#ifndef _SE_VERSION_H_
#define _SE_VERSION_H_

#define STRFILEVER_DEFAULT "2.30.100.1"

// TODO: This file should be generated by the build system from a template file, and the version numbers should be set 
//       from SGX_SDK_VERSION, SDK_VERSION, ENCLAVE_RUNTIME_VERSION variables (see buildenv.mk)
//       For the interim, the STRFILEVER *should* be kept consistent w/ those variables,
//       for the compiled-in version numbers to be consistent w/ the package version numbers.
//       The build system warns about the mismatch as stop-gap measure (ref: '$(warning ...)' entries in buildenv.mk)
#define STRFILEVER STRFILEVER_DEFAULT
#define SDK_MAJOR_VERSION       2
#define SDK_MINOR_VERSION       30
#define SDK_REVISION_VERSION    100
#define MAKE_VERSION_UINT(major,minor,rev)  (((uint64_t)major)<<32 | ((uint64_t)minor) << 16 | rev)
#define VERSION_UINT        MAKE_VERSION_UINT(SDK_MAJOR_VERSION, SDK_MINOR_VERSION, SDK_REVISION_VERSION)

#define COPYRIGHT      "Copyright (C) 2026 Intel Corporation"

// NOTE: Legacy compiled version mismatch (carried from the original SGX repo). To be fixed together with this file templatization (likely level both to ENCLAVE_RUNTIME_VERSION).
#define URTS_VERSION              "2.0.109.0"
#define ENCLAVE_COMMON_VERSION    "1.2.109.0"

#endif
